// Builds dist/refresh.mjs: the whole refresh job (fetchers, planner, app
// template, alerts) as ONE file with zero dependencies.
import { build } from 'esbuild';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');

const app = await build({ entryPoints: [join(here, 'main.js')], bundle: true, format: 'iife', minify: true, write: false, target: 'es2020', legalComments: 'none' });
const appJs = app.outputFiles[0].text.replace(/<\/script/gi, '<\\/script');
const template = await readFile(join(here, 'template.html'), 'utf8');
const rules = JSON.parse(await readFile(join(root, 'alerts.json'), 'utf8')).rules;
await writeFile(join(here, 'generated-assets.js'),
  `// GENERATED by src/app/bundle-refresh.js — do not edit\nexport const APP_JS = ${JSON.stringify(appJs)};\nexport const TEMPLATE = ${JSON.stringify(template)};\nexport const DEFAULT_RULES = ${JSON.stringify(rules)};\n`);

await mkdir(join(root, 'dist'), { recursive: true });
const r = await build({ entryPoints: [join(root, 'src', 'refresh.js')], bundle: true, platform: 'node', format: 'esm', target: 'node20',
  outfile: join(root, 'dist', 'refresh.mjs'), legalComments: 'none',
  banner: { js: '// Cheap Escape refresh job (bundled). Source: branch cheap-escape of the company-brief repo.' } });
console.log(`built dist/refresh.mjs${r.errors.length ? ' WITH ERRORS' : ''}`);
